create table if not exists meetings (id uuid primary key default gen_random_uuid(), title text not null, description text, host_teacher_id uuid, class_id uuid, scheduled_start timestamptz not null, scheduled_end timestamptz not null, status text default 'scheduled', created_at timestamptz default now(), updated_at timestamptz default now()); alter table meetings enable row level security; create index if not exists idx_meetings_teacher on meetings(host_teacher_id); create index if not exists idx_meetings_class on meetings(class_id);
